-- IMPORTANT:
-- This script recreates the attsystem database tables and demo data.
-- BACK UP your existing database before importing it.
-- ================================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `attsystem` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `attsystem`;

DROP VIEW IF EXISTS `reports`;
DROP TABLE IF EXISTS `attendance`;
DROP TABLE IF EXISTS `student_courses`;
DROP TABLE IF EXISTS `teacher_courses`;
DROP TABLE IF EXISTS `courses`;
DROP TABLE IF EXISTS `admininfo`;
DROP TABLE IF EXISTS `students`;
DROP TABLE IF EXISTS `teachers`;
DROP TABLE IF EXISTS `semesters`;
DROP TABLE IF EXISTS `id_counters`;

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE `semesters` (
  `sem_id` int NOT NULL AUTO_INCREMENT,
  `academic_year` varchar(9) NOT NULL,
  `semester_no` tinyint unsigned NOT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`sem_id`),
  UNIQUE KEY `uq_semester` (`academic_year`,`semester_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `students` (
  `st_id` int NOT NULL AUTO_INCREMENT,
  `student_code` varchar(20) NOT NULL,
  `st_name` varchar(255) NOT NULL,
  `st_dept` varchar(255) NOT NULL,
  `st_batch` varchar(255) NOT NULL,
  `st_sem` varchar(255) NOT NULL,
  `st_email` varchar(255) NOT NULL,
  `st_phone` varchar(30) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`st_id`),
  UNIQUE KEY `uq_student_code` (`student_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `teachers` (
  `tc_id` int NOT NULL AUTO_INCREMENT,
  `teacher_code` varchar(20) NOT NULL,
  `tc_name` varchar(255) NOT NULL,
  `tc_dept` varchar(255) NOT NULL,
  `tc_email` varchar(255) NOT NULL,
  `tc_course` varchar(255) DEFAULT NULL,
  `tc_phone` varchar(30) DEFAULT NULL,
  `tc_designation` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`tc_id`),
  UNIQUE KEY `uq_teacher_code` (`teacher_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `admininfo` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `fname` varchar(255) NOT NULL,
  `phone` varchar(30) NOT NULL,
  `type` varchar(30) NOT NULL,
  `st_id` int DEFAULT NULL,
  `tc_id` int DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_username` (`username`),
  UNIQUE KEY `uq_acc_student` (`st_id`),
  UNIQUE KEY `uq_acc_teacher` (`tc_id`),
  CONSTRAINT `fk_acc_student` FOREIGN KEY (`st_id`) REFERENCES `students` (`st_id`),
  CONSTRAINT `fk_acc_teacher` FOREIGN KEY (`tc_id`) REFERENCES `teachers` (`tc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `courses` (
  `course_id` int NOT NULL AUTO_INCREMENT,
  `course_code` varchar(30) NOT NULL,
  `course_name` varchar(255) NOT NULL,
  `credits` tinyint unsigned DEFAULT NULL,
  `department` varchar(100) NOT NULL DEFAULT '',
  `sem_id` int NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'active',
  PRIMARY KEY (`course_id`),
  UNIQUE KEY `uq_course_sem` (`course_code`,`sem_id`),
  KEY `idx_courses_sem` (`sem_id`),
  CONSTRAINT `fk_courses_sem` FOREIGN KEY (`sem_id`) REFERENCES `semesters` (`sem_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `teacher_courses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tc_id` int NOT NULL,
  `course_id` int NOT NULL,
  `assigned_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_teacher_course` (`tc_id`,`course_id`),
  KEY `idx_tcourse_course` (`course_id`),
  CONSTRAINT `fk_tcourse_teacher` FOREIGN KEY (`tc_id`) REFERENCES `teachers` (`tc_id`),
  CONSTRAINT `fk_tcourse_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `student_courses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `st_id` int NOT NULL,
  `course_id` int NOT NULL,
  `enrolled_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_student_course` (`st_id`,`course_id`),
  KEY `idx_scourse_course` (`course_id`),
  CONSTRAINT `fk_scourse_student` FOREIGN KEY (`st_id`) REFERENCES `students` (`st_id`),
  CONSTRAINT `fk_scourse_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `attendance` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stat_id` int NOT NULL,
  `st_status` varchar(20) NOT NULL,
  `stat_date` date NOT NULL,
  `course_id` int NOT NULL,
  `sem_id` int NOT NULL,
  `teacher_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_attendance` (`stat_id`,`course_id`,`stat_date`),
  KEY `idx_att_course` (`course_id`),
  KEY `idx_att_sem` (`sem_id`),
  KEY `idx_att_teacher` (`teacher_id`),
  CONSTRAINT `fk_att_student` FOREIGN KEY (`stat_id`) REFERENCES `students` (`st_id`),
  CONSTRAINT `fk_att_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `fk_att_sem` FOREIGN KEY (`sem_id`) REFERENCES `semesters` (`sem_id`),
  CONSTRAINT `fk_att_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`tc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `id_counters` (
  `prefix` varchar(10) NOT NULL,
  `next_no` int NOT NULL,
  PRIMARY KEY (`prefix`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


