CREATE OR REPLACE SQL SECURITY INVOKER VIEW `reports` AS
SELECT
  s.`st_id` AS `st_id`,
  s.`st_name` AS `st_name`,
  s.`st_dept` AS `st_dept`,
  s.`st_batch` AS `st_batch`,
  a.`stat_date` AS `stat_date`,
  a.`st_status` AS `st_status`,
  c.`course_code` AS `course`,
  a.`course_id` AS `course_id`,
  a.`sem_id` AS `sem_id`,
  a.`teacher_id` AS `teacher_id`
FROM `attendance` a
JOIN `students` s ON s.`st_id` = a.`stat_id`
JOIN `courses` c ON c.`course_id` = a.`course_id`;

SET FOREIGN_KEY_CHECKS = 1;
